    pincode: string;
  };
}

export interface ABDMHealthRecord {
  careContextReference: string;
  display: string;
  hiType: string;
  recordDate: string;
  data: {
    resourceType: string;
    status: string;
    category?: string;
    code?: {
      coding: Array<{
        system: string;
        code: string;
        display: string;
      }>;
    };
  };
}

